gold.schema_ddl:
CREATE TABLE citta (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    cap TEXT NOT NULL UNIQUE,
    regione TEXT NOT NULL
);

CREATE TABLE magazzino (
    id SERIAL PRIMARY KEY,
    citta_id INT NOT NULL UNIQUE REFERENCES citta(id),
    nome TEXT NOT NULL,
    superficie_mq NUMERIC(10,2) CHECK (superficie_mq > 0),
    attivo BOOLEAN DEFAULT TRUE
);
